// Synthetic demonstration dataset for the HumanFactor dashboard.
//
// Responses are generated by a simple, explicit model (below) and stored through the
// same functions the API uses (createSession / validateAndScore / insertResponse), so the
// rows are structurally identical to real ones. They must only ever be written to a
// separate demo database: see checkDemoTarget() and server/scripts/demo-seed.ts.
//
// Model
// - Each simulated participant has a latent ability θ ~ N(0, 1), shifted by field of
//   study and prior training.
// - Single-choice items follow a 2-parameter logistic model P = 1 / (1 + e^(−a(θ − b))).
//   Wrong answers split between "I'm not sure" (likelier at low θ) and distractors,
//   one of which is the dominant misconception for that item.
// - The multi-select item picks each option independently with θ-dependent odds.
// - POST ability = θ + testing effect + a campaign gain that is larger for people who
//   report seeing the campaign; items the campaign targeted get easier.
// - Confidence is weakly related to θ and inflated; the self-estimate overshoots the
//   actual number correct (more at PRE than at POST).

import { resolve } from "node:path";
import { generateCode } from "../../shared/participantCode.js";
import type { Answers, Stage } from "../../shared/types.js";
import { createSession, getSession, insertResponse, type DB } from "../db.js";
import { validateAndScore } from "../scoring.js";
import { KNOWLEDGE_MAX } from "../survey/definition.js";

export interface DemoOptions {
  seed?: number;
  /** Number of completed PRE responses. */
  preN?: number;
  /** Reference "now"; the timeline ends shortly before it. */
  now?: number;
}

export interface DemoSummary {
  preSessions: number;
  preResponses: number;
  postSessions: number;
  postResponses: number;
  matchedPairs: number;
}

// --- randomness ----------------------------------------------------------------------

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

class Rng {
  private next: () => number;
  constructor(seed: number) {
    this.next = mulberry32(seed);
  }
  u() {
    return this.next();
  }
  normal(mean = 0, sd = 1) {
    const u1 = Math.max(this.u(), 1e-12);
    const u2 = this.u();
    return mean + sd * Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
  }
  chance(p: number) {
    return this.u() < p;
  }
  weighted<T>(items: [T, number][]): T {
    const total = items.reduce((s, [, w]) => s + w, 0);
    let x = this.u() * total;
    for (const [item, w] of items) {
      if ((x -= w) < 0) return item;
    }
    return items[items.length - 1][0];
  }
  bytes(n: number) {
    return Uint8Array.from({ length: n }, () => Math.floor(this.u() * 256));
  }
  uuid() {
    const b = this.bytes(16);
    b[6] = (b[6] & 0x0f) | 0x40;
    b[8] = (b[8] & 0x3f) | 0x80;
    const h = [...b].map((x) => x.toString(16).padStart(2, "0")).join("");
    return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
  }
}

const logistic = (x: number) => 1 / (1 + Math.exp(-x));
const clamp = (x: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, x));

// --- item model ----------------------------------------------------------------------

interface SingleItem {
  id: string;
  a: number;
  b: number;
  correct: string;
  /** Distractor ids with relative attractiveness; the first is the dominant misconception. */
  distractors: [string, number][];
  /** Extra ease at POST for items the campaign covered directly. */
  targeted?: boolean;
}

const SINGLE_ITEMS: SingleItem[] = [
  { id: "k01_account_email", a: 1.3, b: -0.5, correct: "c", distractors: [["a", 0.55], ["d", 0.25], ["b", 0.2]] },
  { id: "k02_real_url", a: 1.5, b: 0.6, correct: "c", distractors: [["a", 0.55], ["b", 0.3], ["d", 0.15]], targeted: true },
  { id: "k03_padlock", a: 1.2, b: 0.5, correct: "b", distractors: [["a", 0.6], ["c", 0.25], ["d", 0.15]], targeted: true },
  { id: "k05_parcel_sms", a: 1.1, b: -1.1, correct: "c", distractors: [["b", 0.6], ["a", 0.25], ["d", 0.15]] },
  { id: "k06_mfa_fatigue", a: 1.4, b: 0.35, correct: "c", distractors: [["d", 0.6], ["b", 0.25], ["a", 0.15]] },
  { id: "k07_code_request", a: 1.3, b: -0.2, correct: "b", distractors: [["a", 0.55], ["c", 0.3], ["d", 0.15]], targeted: true },
  { id: "k08_gift_cards", a: 1.0, b: -1.3, correct: "c", distractors: [["b", 0.55], ["d", 0.3], ["a", 0.15]] },
  { id: "k09_qr_code", a: 1.2, b: 0.1, correct: "c", distractors: [["b", 0.5], ["a", 0.3], ["d", 0.2]], targeted: true },
  { id: "k10_after_click", a: 1.2, b: -0.3, correct: "c", distractors: [["b", 0.55], ["d", 0.3], ["a", 0.15]] },
];

/** Multi-select warning signs: true signs get likelier with θ, distractors less likely. */
function warningSigns(theta: number, rng: Rng): string[] {
  if (rng.chance(clamp(0.06 - 0.03 * theta, 0.01, 0.12))) return ["unsure"];
  const picks: string[] = [];
  const truths: [string, number][] = [
    ["urgency", -1.8],
    ["credentials", -1.5],
    ["mismatch", -0.4],
    ["attachment", -0.2],
  ];
  for (const [id, b] of truths) if (rng.chance(logistic(1.2 * (theta - b)))) picks.push(id);
  if (rng.chance(clamp(0.26 - 0.08 * theta, 0.05, 0.4))) picks.push("logo");
  if (rng.chance(clamp(0.14 - 0.05 * theta, 0.03, 0.3))) picks.push("hours");
  return picks.length ? picks : ["urgency"];
}

function answerItems(theta: number, stage: Stage, rng: Rng): Answers {
  const answers: Answers = {};
  for (const item of SINGLE_ITEMS) {
    const b = stage === "post" && item.targeted ? item.b - 0.3 : item.b;
    if (rng.chance(logistic(item.a * (theta - b)))) {
      answers[item.id] = item.correct;
    } else if (rng.chance(clamp(0.3 - 0.12 * theta, 0.1, 0.5))) {
      answers[item.id] = "unsure";
    } else {
      answers[item.id] = rng.weighted(item.distractors);
    }
  }
  answers.k04_warning_signs = warningSigns(theta, rng);
  return answers;
}

// --- people and timeline -----------------------------------------------------------------

interface Person {
  theta: number;
  demographics: Answers;
}

function makePerson(rng: Rng): Person {
  const demographics: Answers = {};
  let shift = 0;
  if (!rng.chance(0.08)) {
    demographics.d_year = rng.weighted<string>([
      ["y1", 0.28],
      ["y2", 0.26],
      ["y3", 0.2],
      ["y4", 0.12],
      ["pg", 0.07],
      ["other", 0.02],
      ["prefer_not", 0.05],
    ]);
  }
  if (!rng.chance(0.08)) {
    const field = rng.weighted<string>([
      ["computing", 0.22],
      ["stem", 0.18],
      ["business", 0.2],
      ["humanities", 0.18],
      ["health", 0.12],
      ["other", 0.05],
      ["prefer_not", 0.05],
    ]);
    demographics.d_field = field;
    if (field === "computing") shift += 0.5;
    if (field === "stem") shift += 0.15;
  }
  if (!rng.chance(0.06)) {
    const training = rng.weighted<string>([
      ["yes", 0.3],
      ["no", 0.5],
      ["unsure", 0.15],
      ["prefer_not", 0.05],
    ]);
    demographics.d_training = training;
    if (training === "yes") shift += 0.25;
  }
  return { theta: rng.normal() + shift, demographics };
}

const DAY = 24 * 60 * 60 * 1000;

/** A timestamp on a random day of the window, biased towards 10:00–22:00. */
function timestampIn(rng: Rng, start: number, days: number): number {
  const day = Math.floor(rng.u() * days);
  const hour = rng.weighted<number>(
    Array.from({ length: 24 }, (_, h) => [h, h < 7 ? 0.15 : h < 10 ? 0.7 : h <= 22 ? 1.6 : 0.6] as [number, number]),
  );
  return start + day * DAY + hour * 60 * 60 * 1000 + Math.floor(rng.u() * 60 * 60 * 1000);
}

function durationMs(rng: Rng, medianSeconds: number): number {
  return Math.max(90, Math.exp(rng.normal(Math.log(medianSeconds), 0.4))) * 1000;
}

function confidence(theta: number, boost: number, rng: Rng): number {
  return Math.round(clamp(3.1 + boost + 0.35 * theta + rng.normal(0, 0.85), 1, 5));
}

function exposure(rng: Rng): { answer: string[]; exposed: boolean | null } {
  const u = rng.u();
  if (u < 0.7) {
    const channels: [string, number][] = [
      ["social_posts", 0.75],
      ["videos", 0.45],
      ["posters", 0.35],
      ["session", 0.2],
      ["quiz", 0.25],
    ];
    const picks = channels.filter(([, p]) => rng.chance(p)).map(([id]) => id);
    return { answer: picks.length ? picks : ["social_posts"], exposed: true };
  }
  if (u < 0.92) return { answer: ["none"], exposed: false };
  return { answer: ["unsure"], exposed: null };
}

// --- generation ---------------------------------------------------------------------------

export function generateDemoData(db: DB, opts: DemoOptions = {}): DemoSummary {
  const rng = new Rng(opts.seed ?? 2026);
  const preN = opts.preN ?? 64;
  const now = opts.now ?? Date.now();
  const preStart = now - 21 * DAY;
  const postStart = now - 5 * DAY;
  const usedCodes = new Set<string>();
  const newCode = () => {
    let code: string;
    do code = generateCode((n) => rng.bytes(n));
    while (usedCodes.has(code));
    usedCodes.add(code);
    return code;
  };

  const summary: DemoSummary = { preSessions: 0, preResponses: 0, postSessions: 0, postResponses: 0, matchedPairs: 0 };

  const submit = (stage: Stage, code: string | null, startedAt: number, medianSeconds: number, answers: Answers) => {
    const id = rng.uuid();
    createSession(db, { id, stage, participantCode: code, startedAt: new Date(startedAt).toISOString() });
    const submittedAt = new Date(Math.min(startedAt + durationMs(rng, medianSeconds), now - 60_000)).toISOString();
    insertResponse(db, {
      id: rng.uuid(),
      session: getSession(db, id)!,
      scored: validateAndScore(stage, answers),
      knowledgeMax: KNOWLEDGE_MAX,
      submittedAt,
    });
  };

  const abandon = (stage: Stage, code: string | null, start: number, days: number) => {
    createSession(db, { id: rng.uuid(), stage, participantCode: code, startedAt: new Date(timestampIn(rng, start, days)).toISOString() });
  };

  const fullyCorrect = (stage: Stage, answers: Answers) => validateAndScore(stage, { ...answers, s_confidence: 3, s_estimate: 0, ...(stage === "post" ? { r_exposure: ["none"] } : {}) }).fullyCorrect;

  db.transaction(() => {
    const returners: { person: Person; code: string; preTheta: number }[] = [];
    const nonReturnCodes: string[] = [];

    // PRE
    for (let i = 0; i < preN; i++) {
      const person = makePerson(rng);
      const code = newCode();
      const items = answerItems(person.theta, "pre", rng);
      const correct = fullyCorrect("pre", items);
      const answers: Answers = {
        ...person.demographics,
        s_confidence: confidence(person.theta, 0.2, rng),
        ...items,
        s_estimate: Math.round(clamp(correct + 1.5 + rng.normal(0, 1.3), 0, 10)),
      };
      submit("pre", code, timestampIn(rng, preStart, 6), 390, answers);
      summary.preSessions++;
      summary.preResponses++;
      if (rng.chance(0.76)) returners.push({ person, code, preTheta: person.theta });
      else nonReturnCodes.push(code);
    }
    const preAbandoned = Math.round((preN * 0.09) / 0.91);
    for (let i = 0; i < preAbandoned; i++) {
      abandon("pre", newCode(), preStart, 6);
      summary.preSessions++;
    }

    // POST
    const postPeople: { theta: number; code: string | null; matched: boolean }[] = [
      ...returners.map((r) => {
        const lostCode = rng.chance(0.07);
        return { theta: r.preTheta, code: lostCode ? null : r.code, matched: !lostCode };
      }),
      ...Array.from({ length: 4 }, () => ({ theta: makePerson(rng).theta, code: null, matched: false })),
    ];
    for (const p of postPeople) {
      const exp = exposure(rng);
      const gain = exp.exposed ? rng.normal(0.55, 0.35) : rng.normal(0.12, 0.3);
      const theta = p.theta + 0.1 + gain;
      const items = answerItems(theta, "post", rng);
      const correct = fullyCorrect("post", items);
      const answers: Answers = {
        s_confidence: confidence(theta, exp.exposed ? 0.35 : 0.15, rng),
        ...items,
        s_estimate: Math.round(clamp(correct + 0.7 + rng.normal(0, 1.2), 0, 10)),
        r_exposure: exp.answer,
      };
      submit("post", p.code, timestampIn(rng, postStart, 5), 300, answers);
      summary.postSessions++;
      summary.postResponses++;
      if (p.matched) summary.matchedPairs++;
    }
    const postAbandoned = Math.round((postPeople.length * 0.06) / 0.94);
    for (let i = 0; i < postAbandoned; i++) {
      abandon("post", nonReturnCodes[i] ?? null, postStart, 5);
      summary.postSessions++;
    }
  })();

  return summary;
}

// --- safety guard ----------------------------------------------------------------------------

export class DemoTargetError extends Error {}

/**
 * Refuses to write synthetic data into the live database, or into a non-empty database
 * unless the caller explicitly asked for a reset.
 */
export function checkDemoTarget(target: string, livePath: string): void {
  if (target === ":memory:") return;
  if (resolve(target) === resolve(livePath)) {
    throw new DemoTargetError(
      `Refusing to write demo data to ${target}: that is the live DATABASE_PATH. Set DEMO_DATABASE_PATH to a separate file (default ./data/demo.db).`,
    );
  }
}

export function demoTargetFromEnv(env: NodeJS.ProcessEnv = process.env): { target: string; livePath: string } {
  return {
    target: env.DEMO_DATABASE_PATH?.trim() || "./data/demo.db",
    livePath: env.DATABASE_PATH?.trim() || "./data/hlac.db",
  };
}
